import { sendToApi } from '../../models/send-to-api.js';
import { aliasOption, appIdOrNameOption, humanJsonOutputFormatOption } from '../global.options.js';

export const instancesCommand = defineCommand({
  description: 'List the instances of an application',
  since: null,
  options: {
    alias: aliasOption,
    app: appIdOrNameOption,
    format: humanJsonOutputFormatOption,
  },
  args: [],
  async handler(options) {
    const { alias, app: appIdOrName, format } = options;
    const { ownerId, appId } = await Application.resolveId(appIdOrName, alias);

    const instances = await getAllInstances({ id: ownerId, appId }).then(sendToApi);

    switch (format) {
      case 'json': {
        Logger.printJson(instances);
        break;
      }
      case 'human':
      default: {
        if (instances.length === 0) {
          Logger.println('No instance is running for this application');
          break;
        }

        const headers = ['INSTANCE ID', 'STATE', 'SIZE', 'COMMIT', 'DEPLOYMENT', 'CREATED AT'];
        const rows = instances.map((instance) => [
          instance.id,
          instance.state,
          instance.flavor?.name ?? '',
          instance.commit ?? '',
          instance.deployNumber ?? '',
          instance.creationDate != null ? new Date(instance.creationDate).toISOString() : '',
        ]);

        Logger.println(formatTable([headers, ...rows]));
      }
    }
  },
});
